from pathlib import Path
import base64,zlib,subprocess,hashlib,json,sys
sys.stdout.reconfigure(encoding='utf-8',errors='backslashreplace')
r=Path(__file__).resolve().parents[2]; out=Path(__file__).parent
files=['battle/geometry/harold_street_catalog.gd','gameplay/harold_street_art.gd','battle/vehicles/battle_arrival_service.gd','tools/dusk_review/bake_harold_frontage.gd','assets/art/harold_frontage/ground.png']
print(subprocess.check_output(['git','status','--short','--',*files],cwd=r,text=True))
assert not subprocess.check_output(['git','diff','--cached','--name-only'],cwd=r,text=True).strip()
assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=r,text=True).strip()=='d262e8f43f34b889ce72b1705d0f4de36d7e40fd'
hashes={}
for f in files:
 p=r/f; b=out/'baseline'/f; b.parent.mkdir(parents=True,exist_ok=True); assert not b.exists(); data=p.read_bytes(); b.write_bytes(data); hashes[f]=hashlib.sha256(data).hexdigest()
(out/'baseline_hashes.json').write_text(json.dumps(hashes,indent=2))
(out/'check.gd').write_bytes(zlib.decompress(base64.b64decode('')))
note='\n\n## 20260915-harold-scale-01 - Vehicle/street update started\nOwner requested Harold Apartments vehicle sizing and a wider street, with a native screenshot. Verified branch build/arsenal-checkpoint-20260911, HEAD d262e8f, empty index; baseline copies/hashes in tools/harold_scale_20260915/. Shared fleet/bridge standard is1.6x; Harold parked cars still use old dimensions. Apply shared scale to all twelve parked cars and matching physical cover, widen road from12 to20 world units toward south, move lower sidewalk/building strip/lamps/litter together; preserve north frontage and unit scale. Arrival deployment bounds follow widened road. Scope: Harold catalog/art, Harold-only arrival service bounds, ground baker/cache and evidence. Concurrent music/portrait/range sources untouched. Next: native before sample, update/rebake, check clearances and native after screenshot. Existing publication blocker remains separate.\n'
for f in ['docs/DEAD_STREET_HIVE_MIND.md','docs/DEAD_STREET_JOURNAL.md']:
 with (r/f).open('a',encoding='utf-8') as h:h.write(note)
engine=Path(r.parent/'Godot/Godot_v4.7.2-stable_win64_console.exe')
with (out/'before.log').open('w',encoding='utf-8') as log:
 result=subprocess.run([str(engine),'--path',str(r),'--script','res://tools/harold_scale_20260915/check.gd','--position','20,30','--','--before'],stdout=log,stderr=subprocess.STDOUT,timeout=150)
print('BEFORE_EXIT',result.returncode);print((out/'before.log').read_text(encoding='utf-8')[-6000:])